import math, json

def lattice_points_on_circle(R2):
    # number of integer solutions (x,y) to x^2 + y^2 = R2
    cnt = 0
    limit = int(math.isqrt(R2))
    for x in range(-limit, limit+1):
        y2 = R2 - x*x
        if y2 < 0:
            continue
        y = int(math.isqrt(y2))
        if y*y == y2:
            cnt += 1 if y == 0 else 2  # (x, y) and (x, -y)
    return cnt

N = 504
# generate all divisors of N that are multiples of 4
vals = []
for a in range(0, 4):
    for b in range(0, 3):
        for c in range(0, 2):
            d = (2**a)*(3**b)*(7**c)
            if d % 4 == 0:
                vals.append(d)
vals = sorted(set(vals))
# verify each divisor can be realised as a lattice‑point count
realised = []
for n in vals:
    # we only need existence; try to construct a radius using the method from the solution
    # Choose a prime p ≡ 1 (mod 4), e.g., 5.
    # Write n = 4 * 2^{a-2} * 3^{b} * 7^{c}
    # Let exponent of p be a-2, and include squares of 3 and 7 as needed.
    # Compute candidate R^2 and check.
    # factor n back into 2^a * 3^b * 7^c
    a = 0
    temp = n
    while temp % 2 == 0:
        a += 1
        temp //= 2
    b = 0
    while temp % 3 == 0:
        b += 1
        temp //= 3
    c = 0
    while temp % 7 == 0:
        c += 1
        temp //= 7
    # construct R^2 as 5^{a-2} * 3^{2b} * 7^{2c}
    if a < 2:
        continue
    R2 = (5**(a-2)) * (3**(2*b)) * (7**(2*c))
    if lattice_points_on_circle(R2) == n:
        realised.append(n)
    else:
        # fallback brute search for small R
        found = False
        for R in range(1, 1000):
            if lattice_points_on_circle(R*R) == n:
                realised.append(n)
                found = True
                break
        if not found:
            raise ValueError(f"Could not realise n={n}")

print(sum(realised))
print(json.dumps(sorted(realised)))

import itertools, json

def compute():
    target = 50
    nums = list(range(1, 21))
    max_vals = set()
    for r in range(1, len(nums)+1):
        for combo in itertools.combinations(nums, r):
            if sum(combo) == target:
                max_vals.add(max(combo))
    answer = sum(max_vals)
    values = sorted(max_vals)
    print(answer)
    print(json.dumps(values))

if __name__ == "__main__":
    compute()
